code='''def transform(grid):
    src=[row[:] for row in grid]
    g=[row[:] for row in grid]
    counts={}
    for row in src:
        for v in row:
            if v: counts[v]=counts.get(v,0)+1
    color=min(counts,key=counts.get)
    coords=[(i,j) for i,row in enumerate(src) for j,v in enumerate(row) if v==color]
    r0=min(i for i,j in coords); c0=min(j for i,j in coords)
    shape={(i-r0,j-c0) for i,j in coords}
    h=len(g); w=len(g[0]); paint=set()
    for r in range(h):
        for c in range(w):
            cells=[(r+dr,c+dc) for dr,dc in shape]
            if all(0<=i<h and 0<=j<w and src[i][j]==0 for i,j in cells):
                paint.update(cells)
    for i,j in paint: g[i][j]=color
    return g
'''
